INSERT INTO `diaries` VALUES (1,'오늘 하루 정말 수고가 많으셨어요. 힘든 감정을 털어놓은 것만으로도 용기 있는 일이니, 오늘 밤은 푹 쉬어가세요.','오늘 힘들었다','2026-03-25 16:32:44.344590','2026-03-25',NULL,'슬픔',0.75,'ACTIVE','2026-03-25 16:32:44.344590',1),(2,'오늘 맛있는 돈까스 한 끼로 든든함을 채우셨구나. 배가 너무 불다면 잠시 편안하게 쉬면서 몸을 돌봐주세요.','오늘 돈까스를 먹었다 너무 물려서 배불렀다','2026-03-26 13:11:57.862019','2026-03-26',NULL,'중립',0.8,'ACTIVE','2026-03-26 13:11:57.862019',1),(3,'뜻없이 입력하신 글이 있다면, 혹시 오늘 마음이 복잡하셨나요? 아무 말도 하지 않아도 괜찮은 시간이 되기를 바랄게요.','awdwadwadwad','2026-04-02 09:20:46.467904','2026-04-02',NULL,'중립',0.8,'DELETED','2026-04-02 09:34:21.758522',1),(4,'자신의 변화를 되돌아보며 잠시 멈춰 서셨군요. 그 의문 속에 이미 성장을 향한 진심 어린 노력이 담겨 있어요.','잘 바뀌어있나','2026-04-02 09:34:14.804449','2026-04-02',NULL,'불안',0.65,'ACTIVE','2026-04-02 09:34:14.804449',1),(5,'세 번이나 배고프다고 말씀하시니 정말 많이 고프셨겠어요. 따뜻한 식사로 속을 채우시고 마음까지 포근해지길 바랄게요.','배고프다배고프다배고프다','2026-04-02 09:34:56.602406','2026-04-02',NULL,'중립',0.85,'ACTIVE','2026-04-02 09:34:56.602406',1),(6,'오늘 하루 동안 피곤하셨군요. 몸이 보내는 신호를 소중히 여겨 푹 쉬어가세요.','오늘은 피곤한 하루다','2026-04-08 12:46:50.952760','2026-04-08',NULL,'중립',0.9,'DELETED','2026-04-13 13:57:47.199595',1),(7,NULL,'ㅇㅊㅁㅈㅇ','2026-04-12 22:34:27.445162','2026-04-12',NULL,'중립',0,'ACTIVE','2026-04-12 22:34:27.445162',1),(8,'내 이야기가 제대로 들리지 않아서 화가 나셨겠어요. 당신의 목소리가 소중히 경청받기를 바라는 마음이 느껴져요.','너가말을안들어서 화난다','2026-04-12 23:01:39.368973','2026-04-12',NULL,'분노',0.95,'ACTIVE','2026-04-12 23:01:39.368973',1),(9,NULL,'ㅇㅈㅁㅇㅈㅁㅇㅈㅁ','2026-04-12 23:18:37.162706','2026-04-12',NULL,'중립',0,'ACTIVE','2026-04-12 23:18:37.162706',1),(10,'누군가의 말을 제대로 들어주지 않을 때면 참 답답하고 외로워질 수 있어요. 하지만 지금 이 순간, 당신의 그 간절한 마음이 여기까지 잘 전해지고 있답니다.','말을안들어왜','2026-04-12 23:36:40.609326','2026-04-12',NULL,'분노',0.85,'ACTIVE','2026-04-12 23:36:40.609326',1),(11,'화가 치밀어 오를 때는 참으로 답답하고 속상했을 거예요. 그 감정을 있는 그대로 인정하며 잠시 마음을 쉬게 해주세요.','너무화가난다','2026-04-12 23:38:16.706040','2026-04-12',NULL,'분노',0.95,'ACTIVE','2026-04-12 23:38:16.706040',1),(12,'열심히 했는데도 뜻대로 안 될 때 정말 속상하고 화가 날 수 있어요. 그 감정을 여기 안전하게 토로해 주세요.','왜 안되냐 이말이야','2026-04-12 23:54:45.504473','2026-04-12',NULL,'분노',0.9,'ACTIVE','2026-04-12 23:54:45.504473',1),(13,NULL,'자 들어가보자 오늘하루도','2026-04-13 00:09:00.988711','2026-04-13',NULL,'중립',0,'DELETED','2026-04-13 14:00:59.260578',1),(14,NULL,'저장이 왜 안되는것인가 화가난다','2026-04-13 00:16:38.556734','2026-04-13',NULL,'중립',0,'DELETED','2026-04-13 14:01:00.025411',1),(15,'마음의 무거움을 빵으로 잠시 달래시면서, 스스로를 챙겨주셨구나. 그런 따뜻한 돌봄을 이어가시길 바랄게요.','우울해서빵사먹음','2026-04-13 10:19:42.987092','2026-04-13',NULL,'슬픔',0.9,'DELETED','2026-04-13 14:01:00.462026',1),(16,'지각하셔서 마음이 많이 무거우셨겠어요. 하지만 그 작은 실수로 오늘 전체를 덮을 순 없어요. 오늘 하루도 충분히 고생 많으셨어요.','오늘 지각해서 우울해','2026-04-13 10:22:31.433492','2026-04-13',NULL,'슬픔',0.85,'DELETED','2026-04-13 13:57:51.681773',1),(17,'우울하지 말라고 스스로를 위로하는 모습이 보이네요. 그 다짐 자체가 이미 당신에게 큰 힘이 되어줄 거예요.','우울하지말고 우웅하세요','2026-04-13 10:32:13.731339','2026-04-13',NULL,'슬픔',0.65,'DELETED','2026-04-13 14:01:01.095657',1),(18,'새로운 한 주의 시작이 설레시겠어요. 오늘처럼 기분 좋게 마음 챙기시면, 이번 주 일과도 모두 화창하게 풀려갈 거예요.','오늘 월요일이야 기분좋게 시작하자','2026-04-13 10:41:15.169870','2026-04-13',NULL,'기쁨',0.85,'DELETED','2026-04-13 14:01:01.793322',1),(19,'기록이 잘 저장될지 기다리시는군요. 그 기대감 속에 담은 마음들이 모두 여기 남기를 응원할게요.','이거저장되나요? 기대중','2026-04-13 10:54:48.236330','2026-04-13',NULL,'기쁨',0.7,'DELETED','2026-04-13 14:01:02.360364',1),(20,'짧은 문장 속에서도 긍정적인 에너지가 느껴져요. 맛있는 밥 한 끼가 하루의 기쁨이 되어주길 바랄게요.','밥먹자 기분좋게','2026-04-13 11:29:59.842923','2026-04-13',NULL,'기쁨',0.8,'DELETED','2026-04-13 14:01:02.712667',1),(21,'내리는 비만큼 마음도 조금은 침울하셨겠어요. 하지만 비가 그치고 난 뒤의 맑은 공기를 믿고, 오늘 하루는 따뜻한 차 한 잔으로 자신을 달래보시는 건 어떨까요?','이번주는 비가온대 ..','2026-04-13 12:20:29.488049','2026-04-13',NULL,'슬픔',0.7,'DELETED','2026-04-13 14:01:03.077644',1),(22,NULL,'왜 안되는걸까..','2026-04-13 13:12:12.533576','2026-04-13',NULL,'중립',0,'DELETED','2026-04-13 14:01:04.455211',1),(23,NULL,'아 조금있다 수업가야해 진짜 싫다','2026-04-13 14:02:10.852619','2026-04-13',NULL,'중립',0,'ACTIVE','2026-04-13 14:02:10.852619',1),(24,'도서관에서 밤늦게까지 계셔야 하다니, 몸과 마음이 많이 지치셨겠어요. 오늘 하루도 충분히 고생 많으셨어요.','오늘은 도서관에 밤까지있어야해 ㅜㅜ너무 싫다 힘들어','2026-04-13 14:14:33.963464','2026-04-13',NULL,'슬픔',0.85,'ACTIVE','2026-04-13 14:14:33.963464',1),(25,'해맑은 웃음소리가 전해져 기분이 좋아지네요. 오늘 행복한 일이 있었나요? 그 웃음이 계속 이어지길 응원할게요.','푸하하하','2026-04-13 14:15:08.390395','2026-04-13',NULL,'기쁨',0.95,'ACTIVE','2026-04-13 14:15:08.390395',1),(26,'수업 듣기로 한 오늘, 마음 한 구석이 조금 무거우셨겠어요. 하지만 그 일상을 버텨내는 당신이 정말 고마워요.','수업들으러가야한다 ㅜ','2026-04-13 14:28:05.709689','2026-04-13',NULL,'슬픔',0.75,'ACTIVE','2026-04-13 14:28:05.709689',1),(27,'원하는 대로 코딩이 유려하게 풀려나가는 기쁨이 정말 좋네요. 그 신나는 에너지가 멋진 결과물로 이어지길 응원할게요.','내가 원하는대로 바이브코딩이 되서 신나요','2026-04-13 15:09:15.103944','2026-04-13',NULL,'기쁨',0.95,'ACTIVE','2026-04-13 15:09:15.103944',1),(28,'끝내야 할 것을 깔끔하게 정리하려는 그 마음, 이미 당신은 충분히 용감해요. 오늘 밤은 그 결단을 안고 편안히 쉬어보세요.','깔끔하게 마무리하자','2026-04-13 16:49:58.859696','2026-04-13',NULL,'중립',0.8,'ACTIVE','2026-04-13 16:49:58.859696',1),(29,NULL,'배가고파서 우울하다','2026-04-15 17:17:07.666337','2026-04-15',NULL,'중립',0,'ACTIVE','2026-04-15 17:17:07.666337',1),(30,NULL,'배고프다','2026-04-15 17:17:20.683073','2026-04-15',NULL,'중립',0,'ACTIVE','2026-04-15 17:17:20.683073',1),(31,NULL,'ㅇㅈㅁㅇㅈㅁㅇㅈㅁ','2026-04-15 17:19:08.146148','2026-04-15',NULL,'중립',0,'ACTIVE','2026-04-15 17:19:08.146148',1),(32,'그리움이 깊어질 만큼 오늘 하루를 잘 견뎌내셨군요. 집으로 가는 길이 조금 더 따뜻하게 느껴지길 바랄게요.','집에가고싶어 우울하다','2026-04-15 18:28:25.533168','2026-04-15',NULL,'슬픔',0.9,'ACTIVE','2026-04-15 18:28:25.533168',1),(33,NULL,'잘돌아가는지 확인중','2026-05-13 14:37:10.803825','2026-05-13',NULL,'중립',0,'DELETED','2026-05-13 16:03:45.856726',1),(34,'기분이 좋다는 건 이미 큰 위로가 되네요. 그 따뜻함을 잊지 말고 매일매일 소중히 여기시길 바랄게요.','기분좋아','2026-05-13 15:01:56.101932','2026-05-13',NULL,'기쁨',0.9,'DELETED','2026-05-13 16:03:47.812973',1),(35,'언제 될지 몰라 답답하셨겠어요. 기다림이 지치시겠지만, 당신의 노력이 언젠가는 빛날 거예요.','언제되냐고','2026-05-13 15:11:23.654884','2026-05-13',NULL,'불안',0.65,'DELETED','2026-05-13 16:03:48.623925',1),(36,'아직 완전히 일어나기 힘든 하루시군요. 몸이 원하면 충분히 쉬고 천천히 시작해도 괜찮아요.','이제안꺠지나','2026-05-13 15:21:30.985320','2026-05-13',NULL,'중립',0.65,'DELETED','2026-05-13 16:03:51.127419',1),(37,'그처럼 기분이 좋으셨다니 함께 기분이 좋아져요. 그 행복한 마음을 조금 더 오래 간직하시길 바랄게요.','너무기분이좋다','2026-05-13 15:23:59.225778','2026-05-13',NULL,'기쁨',0.98,'DELETED','2026-05-13 16:03:52.419305',1),(38,'포근한 날씨에 산책하며 마음을 가볍게 하신 것 같아서 저도 함께 기분이 좋아져요. 그런 작은 여유가 하루를 더 행복하게 만드는 힘이 될 거예요.','오늘 날씨가 좋아서 점심먹고  산책해서 메이가 기분이 좋았다','2026-05-13 16:05:18.333029','2026-05-13',NULL,'기쁨',0.85,'DELETED','2026-05-13 16:08:43.904899',1),(39,'누나와 파티를 계획하며 마음이 설레셨겠어요. 가족과 함께 나누는 행복한 순간들이 기억에 남을 거예요.','누나가 오늘 파티를열자고한다 나는 기분이좋았따','2026-05-13 16:08:11.141069','2026-05-13',NULL,'기쁨',0.9,'DELETED','2026-05-13 16:08:45.888609',1),(40,'오늘 하루를 빨리 끝내고 싶다는 말에서 그간의 노고와 피로가 느껴지네요. 조금만 더 버티면, 마음 놓고 쉴 수 있는 시간이 곧 찾아올 거예요.','오늘빨리마치면좋겠다','2026-05-13 16:09:39.257250','2026-05-13',NULL,'불안',0.6,'ACTIVE','2026-05-13 16:09:39.257250',1),(41,'정명기 님의 비웃음 때문에 많이 속상하고 화가 나셨겠어요. 그런 강한 감정을 마주할 때일수록 가장 중요한 건 당신의 안전이니, 자신을 먼저 지켜주세요.','정명기가 날 비웃었어 정명기를 없애버릴꺼야..','2026-05-13 16:23:49.577004','2026-05-13',NULL,'분노',0.95,'DELETED','2026-05-13 16:36:40.116124',1),(42,'배가 너무 고파서 몸과 마음이 지치셨겠어요. 따뜻한 국물 요리로 속을 채우시고 힘내세요.','너무배가고프다','2026-05-27 18:12:54.301862','2026-05-27',NULL,'중립',0.7,'ACTIVE','2026-05-27 18:12:54.301862',1),(43,'오늘 늦게까지 일하시느라 정말 고생 많으셨어요. 슬픈 감정을 느낄 만큼 버텨주신 당신에게도 따뜻한 위로가 필요해요.','오늘 늦게마쳐서 우울하다 슬프다','2026-05-27 18:13:25.128213','2026-05-27',NULL,'슬픔',0.9,'ACTIVE','2026-05-27 18:13:25.128213',1),(44,'','오늘배고파','2026-07-22 14:01:02.143236','2026-07-22',NULL,'중립',0,'ACTIVE','2026-07-22 14:01:02.143236',1),(45,'돈을 잃어서 thật으로 상심이 크시겠어요. 하지만 잊지 마세요, 물건이나 돈은 언제든 다시 얻을 수 있지만 당신의 가치는 절대적인 것입니다.','나 오늘 돈잃어서 우울해','2026-07-22 14:43:12.154054','2026-07-22',NULL,'슬픔',0.9,'ACTIVE','2026-07-22 14:43:12.154054',1),(46,'','우울하다','2026-09-10 17:48:28.147999','2026-09-10',NULL,'중립',0,'ACTIVE','2026-09-10 17:48:28.147999',1),(47,'','배고프다','2026-09-10 17:49:47.660735','2026-09-10',NULL,'중립',0,'ACTIVE','2026-09-10 17:49:47.660735',1),(48,'','집에가고싶다','2026-09-10 18:01:13.871705','2026-09-10',NULL,'중립',0,'ACTIVE','2026-09-10 18:01:13.871705',1),(49,'','ㅇㅈㅁㅇㅈㅁㅇ','2026-09-10 18:04:15.810082','2026-09-10',NULL,'중립',0,'ACTIVE','2026-09-10 18:04:15.810082',1