INSERT INTO `recommendations` VALUES (2697,'HOBBY',NULL,0,'기분 좋은 날','기쁨','평소 안 해본 특별한 요리를 만들어 보세요.','새로운 요리 도전'),(2698,'ACTIVITY',NULL,0,'날씨 좋은 날 친구들과 예쁜 돗자리를 펴고 피크닉 어때요?','기쁨',NULL,'한강 피크닉'),(2699,'MOVIE','https://upload.wikimedia.org/wikipedia/ko/3/3a/%EB%9D%BC%EB%9D%BC%EB%9E%9C%EB%93%9C_%ED%8F%AC%EC%8A%A4%ED%84%B0.jpg',0,'음악과 꿈','기쁨','그리고 사랑이 넘치는 눈과 귀가 즐거운 영화','라라랜드'),(2700,'BOOK',NULL,0,'긍정적인 에너지를 모아 새로운 목표를 세우기 좋은 책','기쁨',NULL,'아주 작은 습관의 힘'),(2701,'MOVIE','https://www.netflix.com/title/70261674',0,'매 순간의 소중함을 일깨워주는 따뜻한 영화예요. 지금 느끼는 행복을 더 깊이 음미해 보세요.','기쁨','https://upload.wikimedia.org/wikipedia/ko/e/e1/About_Time_Poster.jpg','어바웃 타임'),(2702,'MOVIE','https://www.netflix.com/title/80045661',0,'새로운 도전에 대한 설렘과 기쁨을 느낄 수 있는 영화입니다. 긍정적인 에너지를 얻고 싶을 때 추천해요.','기쁨','https://upload.wikimedia.org/wikipedia/ko/c/c2/The_Intern_poster.jpg','인턴'),(2703,'BOOK','https://image.aladin.co.kr/product/13565/62/cover500/k262532488_1.jpg',0,'큰 행복은 아닐지라도','기쁨','우리 곁엔 항상 작은 기쁨들이 숨어있다는 걸 알려주는 책이에요.','곰돌이 푸 - 행복한 일은 매일 있어'),(2704,'BOOK','https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=610977',0,'순수한 기쁨과 삶의 소중함을 다시금 깨닫게 해주는 아름다운 이야기입니다.','기쁨','https://image.aladin.co.kr/product/610/97/cover500/8932909470_1.jpg','어린 왕자'),(2705,'ACTIVITY',NULL,0,'소중한 장비들과 함께하는 공간을 더 예쁘게 꾸며보세요. 깨끗한 환경이 기분을 더 맑게 해줄 거예요.','기쁨',NULL,'데스크테리어 정돈하기'),(2706,'ACTIVITY',NULL,0,'평소 가보고 싶었던 예쁜 카페에서 나를 위한 작은 사치를 즐겨보세요.','기쁨',NULL,'동네 카페 투어'),(2707,'HOBBY',NULL,0,'오늘의 기쁜 에너지를 모아 작지만 유용한 기능을 직접 구현해 보는 건 어떨까요? 성취감이 두 배가 될 거예요.','기쁨',NULL,'나만의 100 줄 코드 챌린지'),(2708,'HOBBY',NULL,0,'행복한 오늘의 장면들을 아날로그 감성으로 기록해 보세요. 인화할 때의 설렘이 기다려질 거예요.','기쁨',NULL,'일회용 카메라로 일상 담기'),(2719,'HOBBY',NULL,0,'따뜻한 차 한 잔과 함께 내 감정을 다이어리에 쏟아내 보세요.','슬픔',NULL,'다이어리 꾸미기'),(2720,'ACTIVITY',NULL,0,'포근한 이불 속에서 좋아하는 간식을 먹으며 푹 쉬어가는 시간','슬픔',NULL,'이불 속 휴식'),(2721,'MOVIE',NULL,0,'슬픔이라는 감정이 우리에게 주는 진짜 의미를 찾아가는 여정','슬픔','https://upload.wikimedia.org/wikipedia/ko/c/c5/%EC%9D%B8%EC%82%AC%EC%9D%B4%EB%93%9C_%EC%95%84%EC%9B%83_%ED%8F%AC%EC%8A%A4%ED%84%B0.jpg','인사이드 아웃'),